const sample = {
  "demo": true,
  "orderId": "WC-990",
  "email": "buyer@example.com",
  "total": 320,
  "currency": "USD",
  "country": "US",
  "financialStatus": "cod",
  "itemCount": 2,
  "shippingMethod": "standard",
  "phone": "+15555550177"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const total = Number(item.total || item.amount || 0);
const country = String(item.country || item.shippingCountry || 'US');
const financial = String(item.financialStatus || item.status || 'paid').toLowerCase();
const tags = [];
let route = 'fulfill';
if (financial === 'refunded' || financial === 'voided') route = 'refund';
else if (financial === 'pending' || financial === 'cod') route = 'verify-payment';
else if (total >= 250) route = 'vip';
else if (['BR', 'IN', 'NG'].includes(country) && item.shippingMethod === 'express') route = 'fraud-review';
if (Number(item.itemCount || 1) >= 8) tags.push('bulk');
if (route === 'vip') tags.push('vip');
const record = {
  orderId: item.orderId || item.id,
  store: 'WooCommerce',
  email: item.email || '',
  total,
  currency: item.currency || 'USD',
  country,
  financialStatus: financial,
  route,
  tags: tags.join(','),
  title: 'WooCommerce' + ' ' + (item.orderId || ''),
};
return {
  summary: 'WooCommerce' + ' order ' + record.orderId + ' routed to ' + route + ' (' + total + ' ' + record.currency + ').',
  route,
  record,
  slackText: route.toUpperCase() + ' ' + record.orderId + ' for ' + (item.email || 'guest') + ' — ' + total,
  actions: [{ app: 'WooCommerce', operation: route, payload: record }],
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'cod-order-verification',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
